-- Release 207 (deploy/release-crawl-parity.sh) — the business data that migration 207 and its rollback must NOT
-- change, as ONE checksum, computed twice INSIDE the migration's own REPEATABLE READ transaction (before and after,
-- on the same snapshot — a guest's order or an owner's edit at that second can never make it differ; only the
-- migration could). The same tables as release 206 (deploy/seo-engine/guard-tx.sql): whole rows of every table a
-- business owns. One difference: 207 adds two columns to global_products (brand, item_condition — empty), so a
-- product row is compared WITHOUT those two keys (to_jsonb(x) - 'brand' - 'item_condition'): every value the product
-- had before must be identical, and nothing else may change anywhere.
-- Read only. Run: docker exec -i nuriel-shop-db psql -U postgres -d postgres -X -q -tA < guard-tx.sql
SELECT md5(concat_ws('|',
  (SELECT md5(coalesce(string_agg(md5(x::text), ',' ORDER BY md5(x::text)), '')) FROM public.tenants x),
  (SELECT md5(coalesce(string_agg(md5(x::text), ',' ORDER BY md5(x::text)), '')) FROM public.site_settings x),
  (SELECT md5(coalesce(string_agg(md5(x::text), ',' ORDER BY md5(x::text)), '')) FROM public.categories x),
  (SELECT md5(coalesce(string_agg(md5((to_jsonb(x) - 'brand' - 'item_condition')::text), ',' ORDER BY md5((to_jsonb(x) - 'brand' - 'item_condition')::text)), '')) FROM public.global_products x),
  (SELECT md5(coalesce(string_agg(md5(x::text), ',' ORDER BY md5(x::text)), '')) FROM public.orders x),
  (SELECT md5(coalesce(string_agg(md5(x::text), ',' ORDER BY md5(x::text)), '')) FROM public.order_items x),
  (SELECT md5(coalesce(string_agg(md5(x::text), ',' ORDER BY md5(x::text)), '')) FROM public.customer_profiles x),
  (SELECT md5(coalesce(string_agg(md5(x::text), ',' ORDER BY md5(x::text)), '')) FROM public.coupons x),
  (SELECT md5(coalesce(string_agg(md5(x::text), ',' ORDER BY md5(x::text)), '')) FROM public.user_roles x),
  (SELECT md5(coalesce(string_agg(md5(x::text), ',' ORDER BY md5(x::text)), '')) FROM public.tenant_subscriptions x),
  (SELECT md5(coalesce(string_agg(md5(x::text), ',' ORDER BY md5(x::text)), '')) FROM public.billing_history x),
  (SELECT md5(coalesce(string_agg(md5(x::text), ',' ORDER BY md5(x::text)), '')) FROM public.site_tracking x),
  (SELECT md5(coalesce(string_agg(md5(x::text), ',' ORDER BY md5(x::text)), '')) FROM billing.agreements x),
  (SELECT md5(coalesce(string_agg(md5(x::text), ',' ORDER BY md5(x::text)), '')) FROM billing.ledger x),
  (SELECT md5(coalesce(string_agg(md5(x::text), ',' ORDER BY md5(x::text)), '')) FROM billing.settings x),
  (SELECT md5(coalesce(string_agg(md5(x::text), ',' ORDER BY md5(x::text)), '')) FROM billing.upgrade_requests x),
